<html lang="en">
<head>
<meta charset="utf-8">
<title>300 Years of Sclerosponge Thermometry - Academic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --deep-ocean: #0a1628;
    --ocean-dark: #0f2847;
    --ocean-mid: #1a4a7a;
    --ocean-light: #2d6faf;
    --teal: #1a8a8a;
    --warm-amber: #d4920a;
    --warm-orange: #e06b10;
    --hot-red: #c0392b;
    --alert-red: #e74c3c;
    --ice-blue: #a8d8ea;
    --text-white: #f0f4f8;
    --text-light: #c8d6e5;
    --text-muted: #8395a7;
    --card-bg: rgba(15, 40, 71, 0.65);
    --card-border: rgba(45, 111, 175, 0.3);
  }

  body {
    font-family: 'Inter', -apple-system, sans-serif;
    background: linear-gradient(180deg, var(--deep-ocean) 0%, #0d1f3c 30%, #122a4e 60%, #1a3355 80%, #2a1a1a 100%);
    color: var(--text-white);
    width: 33.11in;
    height: 46.81in;
    overflow: hidden;
    position: relative;
  }

  /* Subtle sponge/ocean background texture */
  body::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse 800px 600px at 15% 85%, rgba(26, 138, 138, 0.06) 0%, transparent 70%),
      radial-gradient(ellipse 600px 800px at 85% 15%, rgba(45, 111, 175, 0.08) 0%, transparent 70%),
      radial-gradient(ellipse 1000px 800px at 50% 50%, rgba(212, 146, 10, 0.03) 0%, transparent 70%);
    pointer-events: none;
    z-index: 0;
  }

  .poster {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    padding: 1.2in 1.4in;
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr auto;
    gap: 0.6in;
  }

  /* === HEADER === */
  .header {
    text-align: center;
    border-bottom: 3px solid var(--ocean-light);
    padding-bottom: 0.5in;
  }

  .header .venue-tag {
    display: inline-block;
    background: var(--ocean-mid);
    color: var(--ice-blue);
    font-size: 0.42in;
    font-weight: 600;
    padding: 0.15in 0.5in;
    border-radius: 0.15in;
    letter-spacing: 0.08in;
    text-transform: uppercase;
    margin-bottom: 0.3in;
  }

  .header h1 {
    font-size: 1.35in;
    font-weight: 900;
    line-height: 1.15;
    letter-spacing: -0.02in;
    background: linear-gradient(90deg, var(--ice-blue), #ffffff, var(--warm-amber));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.25in;
  }

  .header h1 .highlight {
    background: linear-gradient(90deg, var(--warm-orange), var(--alert-red));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .header .subtitle {
    font-size: 0.55in;
    font-weight: 300;
    color: var(--text-light);
    line-height: 1.4;
    max-width: 85%;
    margin: 0 auto;
  }

  /* === METRICS STRIP === */
  .metrics-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0.3in;
  }

  .metric-card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 0.2in;
    padding: 0.35in 0.3in;
    text-align: center;
    backdrop-filter: blur(10px);
  }

  .metric-card .metric-value {
    font-size: 0.72in;
    font-weight: 800;
    line-height: 1.1;
  }

  .metric-card .metric-value.red { color: var(--alert-red); }
  .metric-card .metric-value.amber { color: var(--warm-amber); }
  .metric-card .metric-value.blue { color: var(--ocean-light); }
  .metric-card .metric-value.teal { color: var(--teal); }

  .metric-card .metric-label {
    font-size: 0.32in;
    font-weight: 500;
    color: var(--text-muted);
    margin-top: 0.12in;
    line-height: 1.3;
  }

  /* === MAIN CONTENT === */
  .main-content {
    display: grid;
    grid-template-columns: 1fr 2.2fr 1fr;
    grid-template-rows: 1fr;
    gap: 0.5in;
    min-height: 0;
  }

  /* === LEFT COLUMN === */
  .left-col {
    display: flex;
    flex-direction: column;
    gap: 0.5in;
  }

  /* === CENTER (CHART) === */
  .center-col {
    display: flex;
    flex-direction: column;
    gap: 0.4in;
  }

  .chart-container {
    flex: 1;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 0.25in;
    padding: 0.4in;
    position: relative;
    backdrop-filter: blur(10px);
    display: flex;
    flex-direction: column;
  }

  .chart-container .chart-title {
    font-size: 0.55in;
    font-weight: 700;
    color: var(--text-white);
    margin-bottom: 0.15in;
    text-align: center;
  }

  .chart-container .chart-subtitle {
    font-size: 0.35in;
    color: var(--text-muted);
    text-align: center;
    margin-bottom: 0.3in;
  }

  .chart-canvas-wrap {
    flex: 1;
    position: relative;
    min-height: 0;
  }

  .chart-canvas-wrap canvas {
    width: 100%;
    height: 100%;
  }

  /* Threshold badge */
  .threshold-badge {
    position: absolute;
    top: 0.2in;
    right: 0.2in;
    background: linear-gradient(135deg, var(--hot-red), var(--alert-red));
    color: white;
    font-size: 0.38in;
    font-weight: 700;
    padding: 0.18in 0.4in;
    border-radius: 0.12in;
    box-shadow: 0 0.1in 0.3in rgba(231, 76, 60, 0.4);
  }

  /* === RIGHT COLUMN === */
  .right-col {
    display: flex;
    flex-direction: column;
    gap: 0.5in;
  }

  /* === SECTION CARDS === */
  .section-card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 0.2in;
    padding: 0.45in 0.4in;
    backdrop-filter: blur(10px);
  }

  .section-card h2 {
    font-size: 0.52in;
    font-weight: 700;
    color: var(--ice-blue);
    margin-bottom: 0.25in;
    display: flex;
    align-items: center;
    gap: 0.2in;
  }

  .section-card h2 .icon-circle {
    width: 0.6in;
    height: 0.6in;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.3in;
    flex-shrink: 0;
  }

  .section-card p, .section-card li {
    font-size: 0.36in;
    line-height: 1.5;
    color: var(--text-light);
  }

  .section-card ul {
    list-style: none;
    padding: 0;
  }

  .section-card ul li {
    padding: 0.1in 0;
    padding-left: 0.35in;
    position: relative;
  }

  .section-card ul li::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.22in;
    width: 0.12in;
    height: 0.12in;
    border-radius: 50%;
  }

  .section-card.blue-bullets ul li::before { background: var(--ocean-light); }
  .section-card.teal-bullets ul li::before { background: var(--teal); }
  .section-card.amber-bullets ul li::before { background: var(--warm-amber); }
  .section-card.red-bullets ul li::before { background: var(--alert-red); }

  /* === COMPARISON CALLOUT === */
  .comparison-callout {
    background: linear-gradient(135deg, rgba(192, 57, 43, 0.15), rgba(212, 146, 10, 0.15));
    border: 2px solid rgba(231, 76, 60, 0.4);
    border-radius: 0.2in;
    padding: 0.4in;
    text-align: center;
  }

  .comparison-callout h3 {
    font-size: 0.45in;
    font-weight: 700;
    color: var(--warm-amber);
    margin-bottom: 0.25in;
    text-transform: uppercase;
    letter-spacing: 0.05in;
  }

  .comparison-visual {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.4in;
    margin: 0.25in 0;
  }

  .comparison-side {
    text-align: center;
  }

  .comparison-side .comp-value {
    font-size: 1.1in;
    font-weight: 900;
    line-height: 1;
  }

  .comparison-side .comp-label {
    font-size: 0.3in;
    color: var(--text-muted);
    margin-top: 0.1in;
  }

  .comparison-arrow {
    font-size: 0.7in;
    color: var(--alert-red);
    font-weight: 900;
  }

  .comparison-diff {
    font-size: 0.55in;
    font-weight: 800;
    color: var(--alert-red);
    margin-top: 0.15in;
  }

  /* === TABLE === */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.2in;
  }

  .data-table th {
    background: rgba(45, 111, 175, 0.3);
    font-size: 0.3in;
    font-weight: 600;
    color: var(--ice-blue);
    padding: 0.15in 0.2in;
    text-align: left;
  }

  .data-table td {
    font-size: 0.3in;
    color: var(--text-light);
    padding: 0.12in 0.2in;
    border-bottom: 1px solid rgba(45, 111, 175, 0.15);
  }

  .data-table tr:last-child td { border-bottom: none; }

  .data-table .highlight-cell {
    color: var(--warm-amber);
    font-weight: 700;
  }

  /* === TIMELINE MILESTONES === */
  .milestones {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.15in;
    margin-top: 0.2in;
  }

  .milestone {
    background: rgba(26, 74, 122, 0.3);
    border-left: 0.08in solid var(--ocean-light);
    padding: 0.15in 0.2in;
    border-radius: 0 0.1in 0.1in 0;
  }

  .milestone.warm { border-left-color: var(--warm-amber); }
  .milestone.hot { border-left-color: var(--alert-red); }

  .milestone .ms-period {
    font-size: 0.25in;
    font-weight: 700;
    color: var(--ice-blue);
  }

  .milestone .ms-desc {
    font-size: 0.22in;
    color: var(--text-muted);
    line-height: 1.3;
  }

  /* === BOTTOM BAR === */
  .bottom-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-top: 2px solid var(--card-border);
    padding-top: 0.3in;
  }

  .bottom-bar .reference {
    font-size: 0.28in;
    color: var(--text-muted);
    line-height: 1.4;
  }

  .bottom-bar .reference em {
    color: var(--text-light);
    font-style: italic;
  }

  /* === INFOGRAPHIC CONTAINERS === */
  .infographic-wrap {
    flex: 1;
    min-height: 0;
    overflow: hidden;
  }

  .infographic-wrap > div {
    width: 100%;
    height: 100%;
  }
</style>
</head>
<body>

<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="venue-tag">AGU / Nature Climate Change Symposium 2024</div>
    <h1>300 Years of Sclerosponge Thermometry Shows Global Warming Has <span class="highlight">Exceeded 1.5 &deg;C</span></h1>
    <div class="subtitle">Sclerosponge-derived ocean temperature records spanning three centuries reveal that anthropogenic warming has already surpassed the critical 1.5 &deg;C Paris Agreement threshold when measured against a true pre-industrial baseline.</div>
  </div>

  <!-- METRICS STRIP -->
  <div class="metrics-strip">
    <div class="metric-card">
      <div class="metric-value teal">~300 yr</div>
      <div class="metric-label">Record Length<br>(back to ~1700 CE)</div>
    </div>
    <div class="metric-card">
      <div class="metric-value amber">~0.5 &deg;C</div>
      <div class="metric-label">Hidden Pre-Industrial<br>Warming by 1850&ndash;1900</div>
    </div>
    <div class="metric-card">
      <div class="metric-value red">&gt;1.5 &deg;C</div>
      <div class="metric-label">Total Warming (True<br>Pre-Industrial Baseline)</div>
    </div>
    <div class="metric-card">
      <div class="metric-value blue">~1.2 &deg;C</div>
      <div class="metric-label">IPCC-Reported Warming<br>(1850&ndash;1900 Baseline)</div>
    </div>
    <div class="metric-card">
      <div class="metric-value teal">Sr/Ca</div>
      <div class="metric-label">Proxy Source<br>Caribbean Sclerosponges</div>
    </div>
  </div>

  <!-- MAIN CONTENT: 3 columns -->
  <div class="main-content">

    <!-- LEFT COLUMN -->
    <div class="left-col">

      <!-- Why Sclerosponges? -->
      <div class="section-card blue-bullets" style="flex: 1;">
        <h2>
          <span class="icon-circle" style="background: var(--ocean-mid); color: var(--ice-blue);">S</span>
          Why Sclerosponges?
        </h2>
        <p style="margin-bottom: 0.2in;">Sclerosponges are long-lived marine organisms in tropical oceans. Sr/Ca ratios in their aragonite skeletons faithfully track ambient water temperature.</p>
        <ul>
          <li><strong style="color: var(--ice-blue);">Continuous growth</strong> over centuries yields unbroken annual-resolution records</li>
          <li><strong style="color: var(--ice-blue);">Tropical ocean sensitivity</strong> &mdash; Caribbean sites capture large-scale SST variability</li>
          <li><strong style="color: var(--ice-blue);">Independence</strong> from instrumental networks, which only begin around 1850</li>
        </ul>
      </div>

      <!-- Hidden 0.5°C Callout -->
      <div class="comparison-callout" style="flex: 0.7;">
        <h3>The Hidden 0.5 &deg;C</h3>
        <div class="comparison-visual">
          <div class="comparison-side">
            <div class="comp-value" style="color: var(--ocean-light);">1.2&deg;C</div>
            <div class="comp-label">IPCC Reported</div>
          </div>
          <div class="comparison-arrow">&rarr;</div>
          <div class="comparison-side">
            <div class="comp-value" style="color: var(--alert-red);">&gt;1.5&deg;C</div>
            <div class="comp-label">True Total</div>
          </div>
        </div>
        <div class="comparison-diff">+0.5 &deg;C Underestimated</div>
        <p style="font-size: 0.28in; color: var(--text-muted); margin-top: 0.15in;">The 1850&ndash;1900 reference period already contained significant anthropogenic warming</p>
      </div>

      <!-- Data & Methods -->
      <div class="section-card teal-bullets" style="flex: 0.8;">
        <h2>
          <span class="icon-circle" style="background: var(--teal); color: var(--text-white);">M</span>
          Data &amp; Methods
        </h2>
        <ul>
          <li>Caribbean reef environments, 33&ndash;91 m depth</li>
          <li>Sr/Ca ratios measured via ICP-OES</li>
          <li>Calibrated against co-located instrumental SST (1960+), r&sup2; &gt; 0.9</li>
          <li>Validated against HadCRUT5 &amp; NOAA ERSSTv5</li>
          <li>Excellent agreement during instrumental era; divergence only before ~1850</li>
        </ul>
      </div>
    </div>

    <!-- CENTER: CHART -->
    <div class="center-col">
      <div class="chart-container">
        <div class="chart-title">300-Year Temperature Reconstruction</div>
        <div class="chart-subtitle">Sea-surface temperature anomaly relative to the 1700&ndash;1790 true pre-industrial baseline</div>
        <div class="threshold-badge">1.5 &deg;C THRESHOLD EXCEEDED</div>
        <div class="chart-canvas-wrap">
          <canvas id="timelineChart"></canvas>
        </div>
      </div>

      <!-- Milestones below chart -->
      <div style="display: flex; gap: 0.3in;">
        <div class="milestones" style="flex: 1;">
          <div class="milestone">
            <div class="ms-period">1700&ndash;1790</div>
            <div class="ms-desc">Stable pre-industrial temperatures; true baseline</div>
          </div>
          <div class="milestone">
            <div class="ms-period">1790&ndash;1850</div>
            <div class="ms-desc">Onset of detectable warming from early industrialisation</div>
          </div>
          <div class="milestone warm">
            <div class="ms-period">1850&ndash;1900</div>
            <div class="ms-desc">Already ~0.5 &deg;C above true pre-industrial mean</div>
          </div>
          <div class="milestone warm">
            <div class="ms-period">1900&ndash;1960</div>
            <div class="ms-desc">Gradual warming continues; volcanic cooling episodes</div>
          </div>
          <div class="milestone warm">
            <div class="ms-period">1960&ndash;2000</div>
            <div class="ms-desc">Accelerating trend; proxy &amp; instrumental converge</div>
          </div>
          <div class="milestone hot">
            <div class="ms-period">2000&ndash;Present</div>
            <div class="ms-desc">Warming exceeds 1.5 &deg;C vs. true pre-industrial</div>
          </div>
        </div>
      </div>
    </div>

    <!-- RIGHT COLUMN -->
    <div class="right-col">

      <!-- Pre-Industrial Baseline Matters -->
      <div class="section-card amber-bullets" style="flex: 1;">
        <h2>
          <span class="icon-circle" style="background: var(--warm-amber); color: var(--deep-ocean);">B</span>
          Pre-Industrial Baseline Matters
        </h2>
        <p style="margin-bottom: 0.2in;">The IPCC's 1850&ndash;1900 reference period already contained ~0.5 &deg;C of anthropogenic warming, so total warming from a true pre-industrial baseline is substantially higher.</p>
        <table class="data-table">
          <thead>
            <tr>
              <th>Baseline Period</th>
              <th>Warming</th>
