<script>
// === 300-Year Temperature Timeline Chart ===
function drawTimelineChart() {
  const canvas = document.getElementById('timelineChart');
  const wrap = canvas.parentElement;
  const dpr = 2; // Fixed 2x for quality
  const w = wrap.clientWidth;
  const h = wrap.clientHeight;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  // Chart area
  const margin = { top: 50, right: 40, bottom: 70, left: 80 };
  const cw = w - margin.left - margin.right;
  const ch = h - margin.top - margin.bottom;

  // Generate temperature data (approximating the sclerosponge reconstruction)
  const dataPoints = [];
  const years = [];
  for (let yr = 1700; yr <= 2024; yr++) {
    years.push(yr);
    let anomaly;
    if (yr < 1790) {
      // Stable pre-industrial with small natural variability
      anomaly = 0.02 * Math.sin(yr * 0.3) + 0.015 * Math.cos(yr * 0.7) + (Math.random() - 0.5) * 0.04;
    } else if (yr < 1850) {
      // Onset of detectable warming
      const t = (yr - 1790) / 60;
      anomaly = t * 0.15 + 0.02 * Math.sin(yr * 0.3) + (Math.random() - 0.5) * 0.03;
    } else if (yr < 1900) {
      // Already ~0.5°C above; gradual rise
      const t = (yr - 1850) / 50;
      anomaly = 0.15 + t * 0.12 + 0.03 * Math.sin(yr * 0.2) + (Math.random() - 0.5) * 0.03;
    } else if (yr < 1960) {
      // Gradual warming with volcanic dips
      const t = (yr - 1900) / 60;
      let volcanic = 0;
      if (yr >= 1902 && yr <= 1904) volcanic = -0.08;
      if (yr >= 1912 && yr <= 1914) volcanic = -0.1;
      if (yr >= 1963 && yr <= 1965) volcanic = -0.06;
      anomaly = 0.27 + t * 0.25 + volcanic + 0.02 * Math.sin(yr * 0.15) + (Math.random() - 0.5) * 0.03;
    } else if (yr < 2000) {
      // Accelerating warming
      const t = (yr - 1960) / 40;
      anomaly = 0.52 + t * t * 0.4 + t * 0.2 + 0.02 * Math.sin(yr * 0.1) + (Math.random() - 0.5) * 0.03;
    } else {
      // Exceeds 1.5°C
      const t = (yr - 2000) / 24;
      anomaly = 1.12 + t * 0.6 + t * t * 0.15 + 0.015 * Math.sin(yr * 0.1) + (Math.random() - 0.5) * 0.025;
    }
    dataPoints.push(anomaly);
  }

  // Smoothing function
  function smooth(data, window) {
    const result = [];
    for (let i = 0; i < data.length; i++) {
      let sum = 0, count = 0;
      for (let j = Math.max(0, i - window); j <= Math.min(data.length - 1, i + window); j++) {
        sum += data[j];
        count++;
      }
      result.push(sum / count);
    }
    return result;
  }

  const smoothed = smooth(dataPoints, 8);

  // Scale functions
  const yMin = -0.2, yMax = 2.0;
  function xScale(yr) { return margin.left + ((yr - 1700) / (2024 - 1700)) * cw; }
  function yScale(val) { return margin.top + ch - ((val - yMin) / (yMax - yMin)) * ch; }

  // Background grid
  ctx.strokeStyle = 'rgba(45, 111, 175, 0.15)';
  ctx.lineWidth = 1;
  for (let v = 0; v <= 2.0; v += 0.25) {
    const y = yScale(v);
    ctx.beginPath();
    ctx.moveTo(margin.left, y);
    ctx.lineTo(w - margin.right, y);
    ctx.stroke();
  }

  // Y-axis labels
  ctx.fillStyle = '#8395a7';
  ctx.font = '22px Inter, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (let v = 0; v <= 2.0; v += 0.5) {
    ctx.fillText(v.toFixed(1) + ' °C', margin.left - 10, yScale(v));
  }

  // X-axis labels
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  for (let yr = 1700; yr <= 2000; yr += 50) {
    ctx.fillText(yr.toString(), xScale(yr), margin.top + ch + 10);
  }
  ctx.fillText('2024', xScale(2024), margin.top + ch + 10);

  // Axis labels
  ctx.save();
  ctx.translate(18, margin.top + ch / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = '#a8d8ea';
  ctx.font = 'bold 20px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Temperature Anomaly (°C)', 0, 0);
  ctx.restore();

  ctx.fillStyle = '#a8d8ea';
  ctx.font = 'bold 20px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Year', margin.left + cw / 2, margin.top + ch + 50);

  // Axes
  ctx.strokeStyle = 'rgba(45, 111, 175, 0.4)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(margin.left, margin.top);
  ctx.lineTo(margin.left, margin.top + ch);
  ctx.lineTo(w - margin.right, margin.top + ch);
  ctx.stroke();

  // 1.5°C threshold line (prominent)
  const threshY = yScale(1.5);
  ctx.strokeStyle = 'rgba(231, 76, 60, 0.9)';
  ctx.lineWidth = 3;
  ctx.setLineDash([12, 6]);
  ctx.beginPath();
  ctx.moveTo(margin.left, threshY);
  ctx.lineTo(w - margin.right, threshY);
  ctx.stroke();
  ctx.setLineDash([]);

  // 1.5°C threshold label
  ctx.fillStyle = '#e74c3c';
  ctx.font = 'bold 24px Inter, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'bottom';
  ctx.fillText('1.5 °C PARIS THRESHOLD', w - margin.right - 5, threshY - 6);

  // 0.5°C "hidden warming" zone
  const y050 = yScale(0.5);
  const y000 = yScale(0);
  ctx.fillStyle = 'rgba(212, 146, 10, 0.08)';
  ctx.fillRect(margin.left, y050, cw, y000 - y050);
  ctx.fillStyle = 'rgba(212, 146, 10, 0.6)';
  ctx.font = '18px Inter, sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('~0.5 °C hidden warming zone', margin.left + 10, y050 + 5);

  // 1850-1900 baseline zone highlight
  const x1850 = xScale(1850);
  const x1900 = xScale(1900);
  ctx.fillStyle = 'rgba(45, 111, 175, 0.1)';
  ctx.fillRect(x1850, margin.top, x1900 - x1850, ch);
  ctx.strokeStyle = 'rgba(45, 111, 175, 0.3)';
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(x1850, margin.top);
  ctx.lineTo(x1850, margin.top + ch);
  ctx.moveTo(x1900, margin.top);
  ctx.lineTo(x1900, margin.top + ch);
  ctx.stroke();
  ctx.setLineDash([]);

  // IPCC baseline label
  ctx.fillStyle = 'rgba(45, 111, 175, 0.7)';
  ctx.font = '16px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.save();
  const midX = (x1850 + x1900) / 2;
  ctx.translate(midX, margin.top + 30);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('IPCC Baseline 1850–1900', 0, 0);
  ctx.restore();

  // Filled area under curve with gradient
  const gradient = ctx.createLinearGradient(margin.left, 0, w - margin.right, 0);
  gradient.addColorStop(0, 'rgba(26, 74, 122, 0.3)');
  gradient.addColorStop(0.4, 'rgba(26, 138, 138, 0.25)');
  gradient.addColorStop(0.7, 'rgba(212, 146, 10, 0.3)');
  gradient.addColorStop(1, 'rgba(231, 76, 60, 0.35)');

  ctx.beginPath();
  ctx.moveTo(xScale(1700), yScale(0));
  for (let i = 0; i < years.length; i++) {
    ctx.lineTo(xScale(years[i]), yScale(smoothed[i]));
  }
  ctx.lineTo(xScale(2024), yScale(0));
  ctx.closePath();
  ctx.fillStyle = gradient;
  ctx.fill();

  // Main temperature line with gradient color
  // Draw line segments with changing color
  for (let i = 1; i < years.length; i++) {
    const t = i / (years.length - 1);
    let r, g, b;
    if (t < 0.35) {
      // Deep blue to teal
      const s = t / 0.35;
      r = Math.round(26 + s * 0);
      g = Math.round(74 + s * 64);
      b = Math.round(122 + s * 16);
    } else if (t < 0.65) {
      // Teal to amber
      const s = (t - 0.35) / 0.3;
      r = Math.round(26 + s * 186);
      g = Math.round(138 + s * 8);
      b = Math.round(138 - s * 128);
    } else {
      // Amber to red
      const s = (t - 0.65) / 0.35;
      r = Math.round(212 + s * 19);
      g = Math.round(146 - s * 70);
      b = Math.round(10 - s * 10);
    }

    ctx.strokeStyle = `rgb(${r}, ${g}, ${b})`;
    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(xScale(years[i - 1]), yScale(smoothed[i - 1]));
    ctx.lineTo(xScale(years[i]), yScale(smoothed[i]));
    ctx.stroke();
  }

  // Crossing point marker
  let crossingYear = 0;
  for (let i = 1; i < smoothed.length; i++) {
    if (smoothed[i] >= 1.5 && smoothed[i-1] < 1.5) {
      crossingYear = years[i];
      break;
    }
  }

  if (crossingYear > 0) {
    const cx = xScale(crossingYear);
    const cy = yScale(1.5);

    // Glow
    const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, 30);
    glow.addColorStop(0, 'rgba(231, 76, 60, 0.6)');
    glow.addColorStop(1, 'rgba(231, 76, 60, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(cx - 30, cy - 30, 60, 60);

    // Circle
    ctx.beginPath();
    ctx.arc(cx, cy, 8, 0, Math.PI * 2);
    ctx.fillStyle = '#e74c3c';
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Label
    ctx.fillStyle = '#e74c3c';
    ctx.font = 'bold 20px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    ctx.fillText('1.5 °C crossed (~' + crossingYear + ')', cx + 14, cy - 4);
  }

  // Current endpoint marker
  const endX = xScale(2024);
  const endY = yScale(smoothed[smoothed.length - 1]);
  ctx.beginPath();
  ctx.arc(endX, endY, 6, 0, Math.PI * 2);
  ctx.fillStyle = '#e74c3c';
  ctx.fill();
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#e74c3c';
  ctx.font = 'bold 18px Inter, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'bottom';
  ctx.fillText('~1.7 °C (2024)', endX - 10, endY - 8);
}

// Wait for fonts then draw
document.fonts.ready.then(() => {
  drawTimelineChart();
}).catch(() => {
  drawTimelineChart();
});
</script>

